/**
 * 生成管理控制台中的内容页面。
 * @param {string} page 当前功能。
 * @returns {string} 内容标记。
 */
function adminPage(page) {
  switch (page) {
    case 'overview': return adminOverview();
    case 'flows': return adminFlows();
    case 'org': return adminOrg();
    case 'apps': return adminApps();
    case 'runtime': return adminRuntime();
    case 'outbound': return adminOutbound();
    case 'reports': return adminReports();
    case 'system': return adminSystem();
    default: return adminOverview();
  }
}
/**
 * 输出带页签的功能区域。
 * @param {Array} items 页签键和值。
 * @returns {string} 页签标记。
 */
function adminTabs(items) { return `<div class="tabs">${items.map(([id,name])=>`<button data-tab="${id}" class="${adminState.tab===id?'active':''}">${name}</button>`).join('')}</div>`; }
/**
 * 输出信息表格。
 * @param {Array} heads 标题。
 * @param {Array} rows 内容行。
 * @returns {string} 表格标记。
 */
function adminTable(heads,rows) { return `<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${heads.length}" class="admin-empty">没有符合条件的数据，请调整筛选条件。</td></tr>`}</tbody></table></div><div class="admin-summary"><span>共 ${rows.length} 条 · 演示数据</span><div class="admin-pagination"><span>20 条 / 页</span><button class="btn sm" disabled>上一页</button><button class="btn sm primary" disabled>1</button><button class="btn sm" disabled>下一页</button></div></div>`; }
/**
 * 输出状态徽标。
 * @param {string} text 状态文字。
 * @param {string} type 颜色类型。
 * @returns {string} 状态标记。
 */
function adminPill(text,type='ok'){return `<span class="pill ${type}">${text}</span>`;}
/**
 * 输出卡片指标。
 * @param {Array} values 指标列表。
 * @returns {string} 指标标记。
 */
function adminMetrics(values){return `<div class="admin-metrics">${values.map(([label,value,note,color])=>`<article class="admin-metric"><label>${label}</label><strong class="${color||''}">${value}</strong><small>${note}</small></article>`).join('')}</div>`;}
/**
 * 展示运行概览与异常入口。
 * @returns {string} 页面标记。
 */
function adminOverview(){return `<div class="toolbar"><span class="pill ok"><span class="admin-dot"></span>服务运行正常</span><span class="muted">2026 年 10 月 13 日，星期二</span><span class="spacer"></span><button class="btn" data-action="refresh">${UI.icon('refresh')} 刷新</button></div>${adminMetrics([['运行中审批','128','较昨日 +12 · 当前全部部门','blue'],['今日已完成','86','通过 79 · 拒绝 5 · 撤回 2'],['超时待办','7','涉及 3 个流程 · 需要关注','orange'],['待处理回调',String(adminState.queue.filter(q=>q.status!=='成功').length),'最近一次发送：14:32:08']])}<div class="admin-columns"><section class="panel"><div class="panel-head">需要关注 <span class="pill warn">3 项</span></div><div class="panel-body"><div class="admin-mini"><span class="avatar">${UI.icon('alert')}</span><div class="description"><p>采购申请 · 财务复核积压</p><small>5 件待办已超过 2 个工作日，当前处理人：赵敏</small></div><button class="btn sm" data-go="runtime">查看</button></div><div class="admin-mini"><span class="avatar">${UI.icon('send')}</span><div class="description"><p>ERP 回调暂时不可达</p><small>HTTP 503 · 已重试 3 次，下次重试 15:02</small></div><button class="btn sm" data-go="outbound">处理</button></div><div class="admin-mini"><span class="avatar">${UI.icon('user')}</span><div class="description"><p>人员离职待交接</p><small>郑涛 · 采购部 · 2 项在途待办等待转交</small></div><button class="btn sm" data-action="handover">办理交接</button></div></div></section><section class="panel"><div class="panel-head">本周流程处理量 <button class="btn ghost sm" data-go="reports">查看报表 ${UI.icon('chevR')}</button></div><div class="panel-body">${[['费用报销',86,100],['采购申请',64,74],['合同审批',32,37],['用印申请',21,24]].map(([name,value,width])=>`<div class="admin-bar-row"><span>${name}</span><div class="admin-bar-track"><span style="width:${width}%"></span></div><b>${value} 件</b></div>`).join('')}<p class="hint">统计周期：10 月 7 日—10 月 13 日</p></div></section></div><section class="panel"><div class="panel-head">最近管理操作 <button class="btn ghost sm" data-go="system" data-sub="logs">全部日志 ${UI.icon('chevR')}</button></div>${adminTable(['时间','操作人','操作','对象','结果'],adminState.logs.slice(0,4).map(l=>[l.time,l.user,l.action,l.target,adminPill('成功')]))}</section>`;}
/**
 * 展示流程版本管理和模板库。
 * @returns {string} 页面标记。
 */
function adminFlows(){const tab=adminState.tab;return adminTabs([['list','流程管理'],['templates','流程模板库']])+(tab==='templates'?`<div class="admin-callout">模板包含流程规则、审批数据定义与详情排版。复制后在流程设计器中调整；业务单据仍由业务系统创建。</div><div class="admin-template-grid">${['费用报销','采购申请','请假申请','加班申请','出差申请','付款申请','用印申请','合同审批','物品领用','质量异常'].map((n,i)=>`<article class="admin-template"><span class="tile-icon">${UI.icon('layers')}</span><h3>${n}</h3><p>${['多级主管 + 财务复核，包含票据明细与金额条件。','部门负责人 + 比价会签，按预算和物料类型分流。','按申请时长自动匹配审批层级，抄送归档。'][i%3]}</p><footer><span>官方模板 · ${i%3+4} 个节点</span><button class="btn sm" data-action="copy-template" data-name="${n}">使用模板</button></footer></article>`).join('')}</div>`:`<div class="toolbar"><input class="inp" data-filter placeholder="搜索流程名称或编码" value="${UI.escape(adminState.search)}"><select class="sel" data-status><option>全部状态</option><option ${adminState.status==='已发布'?'selected':''}>已发布</option><option ${adminState.status==='草稿'?'selected':''}>草稿</option><option ${adminState.status==='已停用'?'selected':''}>已停用</option></select><span class="spacer"></span><button class="btn" data-action="flow-import">导入流程</button><button class="btn primary" data-action="flow-new">${UI.icon('plus')} 新建流程</button></div><section class="panel">${adminTable(['流程名称 / 编码','当前版本','设计方式','接入应用','状态','更新于','操作'],adminState.flows.filter(f=>(f.name+f.code).toLowerCase().includes(adminState.search.toLowerCase())&&(adminState.status==='全部状态'||f.status===adminState.status)).map(f=>[`<b>${UI.escape(f.name)}</b><span class="sub mono">${UI.escape(f.code)}</span>`,f.version,f.mode,f.app,adminPill(f.status,f.status==='已发布'?'ok':f.status==='草稿'?'warn':''),'10-13 11:26',`<span class="action-links"><a class="btn ghost sm" href="designer.html">设计</a><button class="btn ghost sm" data-action="versions" data-id="${f.code}">版本</button><button class="btn ghost sm" data-action="flow-toggle" data-id="${f.code}">${f.status==='已停用'?'启用':'停用'}</button></span>`]))}</section><p class="hint">已发布版本不可修改。正在运行的审批单始终使用发起时的流程版本。</p>`);}
/**
 * 展示组织人员、角色和审批配置。
 * @returns {string} 页面标记。
 */
function adminOrg(){const tab=adminState.tab;let body='';if(tab==='people'){body=`<div class="toolbar"><input class="inp" data-filter placeholder="搜索姓名 / 工号" value="${UI.escape(adminState.search)}"><span class="spacer"></span><button class="btn" data-action="org-import">导入校验</button><button class="btn" data-action="department">管理部门</button><button class="btn primary" data-action="person-new">新增人员</button></div><div class="admin-tree"><nav class="admin-tree-nav"><b>公司组织</b>${['全部部门','总经办','生产部','生产一部','采购部','财务部','研发部','行政部'].map((n,i)=>`<button data-dept="${n}" class="${i?'indent':''} ${adminState.dept===n?'active':''}">${i?'└ ':''}${n}</button>`).join('')}<p class="hint">可信来源：审批服务<br>人员可归属多个部门</p></nav><section class="panel">${adminTable(['人员 / 工号','部门 / 岗位','直属上级','账号状态','操作'],adminState.people.filter(p=>(adminState.dept==='全部部门'||p.dept.includes(adminState.dept))&&(p.name+p.code).includes(adminState.search)).map(p=>[`<b>${p.name}</b><span class="sub mono">${p.code}</span>`,`${p.dept}<span class="sub">${p.job} · ${p.level}</span>`,p.manager,adminPill(p.status,p.status==='已离职'?'warn':'ok'),`<button class="btn ghost sm" data-action="person-edit" data-id="${p.code}">编辑</button><button class="btn ghost sm" data-action="account" data-id="${p.code}">账号</button>`]))}</section></div>`;}else if(tab==='bindings'){body=`<div class="toolbar"><select class="sel"><option>ERP 采购系统</option><option>费用报销系统</option></select><span class="spacer"></span><button class="btn" data-action="auto-bind">按工号自动匹配</button><button class="btn primary" data-action="binding">新增绑定</button></div><div class="admin-callout">业务系统推送仅更新绑定与补充字段，不覆盖可信来源的组织信息。绑定完成后可直接使用业务系统的用户 ID 调用接口。</div><section class="panel">${adminTable(['类型','业务系统 ID','审批服务对象','匹配方式','状态','操作'],adminState.bindings.map((b,i)=>[b.type,b.external,b.person,b.mode,adminPill('已绑定'),`<button class="btn ghost sm" data-action="binding" data-id="${i}">调整</button>`]))}</section>`;}else if(tab==='roles'){body=`<div class="toolbar"><span class="muted">角色权限与管理数据范围</span><span class="spacer"></span><button class="btn primary" data-action="role-new">新增角色</button></div><section class="panel">${adminTable(['角色','成员','数据范围','授权功能','操作'],adminState.roles.map((r,i)=>[r.name,r.members,r.scope,r.rights,`<button class="btn ghost sm" data-action="role" data-id="${i}">配置权限</button>`]))}</section>`;}else if(tab==='matrix'){body=`<div class="toolbar"><select class="sel"><option>采购授权矩阵</option></select><span class="muted">修改审批人即时用于后续到达的节点</span><span class="spacer"></span><button class="btn primary" data-action="matrix-new">新增规则</button></div><section class="panel">${adminTable(['优先级','部门','金额区间','物料类别','审批人','操作'],adminState.matrix.map((r,i)=>[i+1,r.dept,r.amount,r.category,r.person,`<button class="btn ghost sm" data-action="matrix" data-id="${i}">编辑</button>`]))}</section><div class="admin-callout">从上到下匹配规则；未命中时交由流程指定的兜底审批人处理。请确保金额区间不重叠，并为未命中条件保留兜底审批人。</div>`;}else {body=`<div class="toolbar"><b>2026 年 10 月</b><span class="muted">标准工作日历 · 周一至周五 ${adminState.settings.workStart||'09:00'}–${adminState.settings.workEnd||'18:00'}</span><span class="spacer"></span><button class="btn" data-action="calendar-hours">工作时间</button></div><section class="panel"><div class="panel-body"><div class="admin-calendar">${['一','二','三','四','五','六','日'].map(d=>`<div class="weekday">周${d}</div>`).join('')}${Array.from({length:35},(_,i)=>{const d=i-2;return d<1||d>31?'<div class="day off"></div>':`<button class="day ${(i%7>=5)?'off':''} ${adminState.holidays[d]?'holiday':''} ${d===13?'today':''}" data-day="${d}">${d}<small>${adminState.holidays[d]||((i%7>=5)?'休息日':'工作日')}</small></button>`;}).join('')}</div><p class="hint">点击日期维护节假日与调休。节点处理时限按工作日历计算；初版超时只提醒。</p></div></section>`;}return adminTabs([['people','组织人员'],['bindings','业务绑定'],['roles','角色权限'],['matrix','审批矩阵'],['calendar','工作日历']])+body;}
/**
 * 展示接入应用、向导和接口沙箱。
 * @returns {string} 页面标记。
 */
function adminApps(){return adminTabs([['list','接入应用'],['debug','接口调试'],['docs','接入文档']])+(adminState.tab==='debug'?`<div class="admin-callout">本地沙箱：请求只使用演示数据，不访问业务系统。可切换响应场景检查界面反馈。</div><div class="admin-columns"><section class="panel"><div class="panel-head">请求</div><div class="panel-body"><div class="field"><span>应用</span><select class="sel"><option>ERP 采购系统 · erp-demo</option></select></div><div class="field"><span>接口</span><select class="sel" id="api-method"><option>POST /api/v1/flows/PURCHASE_REQUEST/preview</option><option>GET /api/v1/tasks/count?user=EMP001</option><option>POST /api/v1/embed-tokens</option><option>GET /api/v1/instances/demo-001</option></select></div><div class="field"><span>请求体</span><textarea class="inp mono" id="api-body" rows="8">{
  "businessKey": "PO-20261013-001",
  "initiator": "EMP001",
  "data": { "amount": 128000, "department": "采购部" }
}</textarea></div><div class="toolbar"><select class="sel" id="api-scenario"><option>正常响应</option><option>参数错误</option><option>未授权</option><option>状态冲突</option></select><button class="btn primary" data-action="api-run">运行模拟请求</button></div></div></section><section class="panel"><div class="panel-head">响应 <span class="pill" id="api-status">等待请求</span></div><div class="panel-body"><pre class="admin-code" id="api-result">运行请求后，在此查看状态码、响应数据与链路 ID。</pre><p class="hint">当前接口形态为设计示意，正式契约以开放接口文档为准。</p></div></section></div>`:adminState.tab==='docs'?`<section class="panel"><div class="panel-head">从业务系统接入审批服务</div><div class="panel-body"><div class="admin-steps"><span class="active"><b>1</b>注册应用</span>${UI.icon('chevR')}<span><b>2</b>绑定人员</span>${UI.icon('chevR')}<span><b>3</b>选定流程</span>${UI.icon('chevR')}<span><b>4</b>接口联调</span>${UI.icon('chevR')}<span><b>5</b>验证回调</span></div><h3 class="admin-block-title">.NET SDK · 兼容 .NET Framework 4.6.1</h3><pre class="admin-code">// 示意代码：具体签名以发布后的 SDK 为准。
var approval = new ApprovalClient(new ApprovalClientOptions {
    BaseAddress = new Uri("https://approval.example.com/"),
    ApiKey = Environment.GetEnvironmentVariable("APPROVAL_API_KEY")
});
var count = await approval.GetTaskCountAsync(currentUser.Code);
var url = await approval.CreateOpenUrlAsync(taskId, currentUser.Code);</pre><div class="toolbar"><button class="btn" data-action="sdk-download">下载示例代码</button><a class="btn" href="../contracts.md" target="_blank">接口契约</a><a class="btn primary" href="demo.html">打开示例业务系统</a></div><p class="hint">业务系统可跳转、iframe 或 WebView2 内嵌审批中心；也可使用数据接口自行绘制界面。嵌入页面完成审批后通知宿主刷新。</p></div></section>`:`<div class="toolbar"><span class="muted">按应用配置流程授权、回调地址和嵌入来源</span><span class="spacer"></span><button class="btn primary" data-action="app-new">${UI.icon('plus')} 新建接入应用</button></div><section class="panel">${adminTable(['应用 / 编码','授权流程','API Key','回调状态','状态','操作'],adminState.apps.map((a,i)=>[`<b>${UI.escape(a.name)}</b><span class="sub mono">${UI.escape(a.code)}</span>`,a.flows,'•••••••• demo',adminPill(a.callback?'已配置':'未配置',a.callback?'ok':'warn'),adminPill(a.status,a.status==='启用'?'ok':'warn'),`<button class="btn ghost sm" data-action="app-edit" data-id="${i}">配置</button><button class="btn ghost sm" data-action="app-key" data-id="${i}">密钥</button><button class="btn ghost sm" data-action="app-test" data-id="${i}">测试回调</button>`]))}</section><div class="admin-callout">嵌入令牌短时有效、只可兑换一次；只有登记过的来源网站能内嵌审批页面。API Key 不出现在前端业务代码中。</div>`);}
/**
 * 展示运行中审批单与管理操作。
 * @returns {string} 页面标记。
 */
function adminRuntime(){return `<div class="toolbar"><input class="inp" data-filter placeholder="搜索业务单号 / 标题" value="${UI.escape(adminState.search)}"><select class="sel" data-status>${['全部状态','审批中','已终止','已完成'].map(s=>`<option ${s===adminState.status?'selected':''}>${s}</option>`).join('')}</select><span class="spacer"></span><button class="btn" data-action="export">导出明细</button></div><div class="admin-callout">管理员干预必须填写原因，所有操作保留在审批记录中。已提交的业务数据只读；改业务单据需返回来源系统。</div><section class="panel">${adminTable(['审批单 / 来源','当前节点','当前审批人','状态','已停留','操作'],adminState.instances.filter(i=>(i.title+i.id).includes(adminState.search)&&(adminState.status==='全部状态'||i.status===adminState.status)).map(i=>[`<b>${i.title}</b><span class="sub mono">${i.id} · ERP</span>`,i.node,i.person,adminPill(i.status,i.status==='审批中'?'accent':'ok'),`<span class="${i.hours>48?'danger-text':''}">${i.hours} 小时${i.hours>48?' · 已超时':''}</span>`,`<a class="btn ghost sm" href="center.html">详情</a><button class="btn ghost sm" data-action="intervene" data-id="${i.id}">管理干预</button>`]))}</section>`;}
/**
 * 展示出站回调、钩子与重试队列。
 * @returns {string} 页面标记。
 */
function adminOutbound(){return adminTabs([['queue','待发队列'],['hooks','钩子配置']])+(adminState.tab==='hooks'?`<div class="toolbar"><span class="muted">所有外部请求经统一出站适配层</span><span class="spacer"></span><button class="btn primary" data-action="hook-new">新增钩子</button></div><section class="panel">${adminTable(['名称','触发时机','目标应用','超时','失败策略','操作'],adminState.hooks.map((h,i)=>[h.name,h.trigger,h.app,h.timeout,h.policy,`<button class="btn ghost sm" data-action="hook" data-id="${i}">配置</button><button class="btn ghost sm" data-action="hook-test" data-id="${i}">模拟测试</button>`]))}</section>`:`${adminMetrics([['今日已投递','326','回调 128 · 站内消息 198'],['等待重试',String(adminState.queue.filter(q=>q.status==='等待重试').length),'自动退避：1 分钟、5 分钟、30 分钟','orange'],['人工处理',String(adminState.queue.filter(q=>q.status==='已停止').length),'达到重试次数上限'],['投递成功率','99.1%','最近 24 小时']])}<div class="toolbar"><select class="sel" data-status>${['全部状态','等待重试','成功','已停止'].map(s=>`<option ${adminState.status===s?'selected':''}>${s}</option>`).join('')}</select><span class="spacer"></span><button class="btn" data-action="retry-all">重试全部失败项</button></div><section class="panel">${adminTable(['事件 / 业务单号','目标','状态','尝试次数','下次重试','操作'],adminState.queue.filter(q=>adminState.status==='全部状态'||q.status===adminState.status).map(q=>[`<span class="mono">${q.event}</span><span class="sub">${q.business}</span>`,q.target,adminPill(q.status,q.status==='成功'?'ok':q.status==='已停止'?'danger':'warn'),q.attempts,q.status==='成功'?'—':'15:02:08',`<button class="btn ghost sm" data-action="queue-detail" data-id="${q.id}">请求记录</button><button class="btn ghost sm" data-action="retry" data-id="${q.id}" ${q.status==='成功'?'disabled':''}>重试</button>`]))}</section><p class="hint">回调采用至少一次投递；业务系统按 eventId 去重。签名密钥加密保存，演示中不发送实际请求。</p>`);}
/**
 * 展示统计报表及可访问的数值条形图。
 * @returns {string} 页面标记。
 */
function adminReports(){const report=adminState.tab;const factor=adminState.reportPeriod==='本周'?1:4;return `<div class="toolbar"><select class="sel" id="report-period"><option ${factor===1?'selected':''}>本周</option><option ${factor===4?'selected':''}>本月</option></select><select class="sel" id="report-flow"><option>全部流程</option><option ${adminState.reportFlow==='采购申请'?'selected':''}>采购申请</option><option ${adminState.reportFlow==='费用报销'?'selected':''}>费用报销</option></select><select class="sel" id="report-dept"><option>全部部门</option><option ${adminState.reportDept==='采购部'?'selected':''}>采购部</option><option ${adminState.reportDept==='财务部'?'selected':''}>财务部</option></select><select class="sel" id="report-app"><option>全部来源</option><option ${adminState.reportApp==='ERP 采购系统'?'selected':''}>ERP 采购系统</option><option ${adminState.reportApp==='费用报销系统'?'selected':''}>费用报销系统</option></select><button class="btn primary" data-action="report-apply">查询</button><span class="spacer"></span><button class="btn" data-action="report-export">导出报表</button></div>${adminMetrics([['发起量',String(adminReportRows().reduce((sum,r)=>sum+r[1],0)*factor),'按当前时间段与管理范围'],['通过率','91.4%','拒绝 5.2% · 撤回 3.4%'],['平均审批耗时','18.6 h','从发起至结束'],['90% 完成耗时','42.8 h','90% 的审批在此时间内完成']])}${adminTabs([['flow','流程分析'],['node','节点瓶颈'],['people','人员 / 部门']])}<section class="panel"><div class="panel-head">${report==='node'?'节点耗时排行':report==='people'?'人员工作负荷':'流程效率对比'}<span class="hint">最近汇总 14:00 · 今日未汇总部分实时计算</span></div>${report==='node'?`<div class="panel-body">${[['财务复核',18.6,93],['采购会签',12.4,62],['分管领导',6.2,31],['部门负责人',3.8,19]].map(([n,v,w])=>`<div class="admin-bar-row"><span>${n}</span><div class="admin-bar-track" role="img" aria-label="${n}平均停留${v}小时"><span style="width:${w}%"></span></div><b>${v} h</b></div>`).join('')}</div>${adminTable(['节点','平均停留','P90 耗时','超时率','处理量'],[['财务复核','18.6 h','36.2 h','12.4%','62'],['采购会签','12.4 h','24.8 h','6.8%','48'],['分管领导','6.2 h','14.6 h','2.1%','34']])}`:report==='people'?adminTable(['人员','部门','当前积压','平均处理时长','超时次数','处理量'],[['赵敏','财务部','12','8.4 h','3','46'],['吴芳','采购部','8','4.2 h','1','38'],['周总','总经办','5','6.8 h','0','21'],['钱丽','财务部','4','3.6 h','0','42']]):adminTable(['流程','发起量','通过率','拒绝率','撤回率','平均耗时','P90 耗时'],adminReportRows().map(r=>[r[0],r[1]*factor,...r.slice(2)]))}</section><p class="hint">管理员可查看全部；部门负责人只查看管理范围。导出为 Excel 可打开的 CSV 文件，包含当前筛选条件。</p>`;}
/**
 * 返回报表当前筛选的数据。
 * @returns {Array} 流程统计记录。
 */
function adminReportRows(){return [['费用报销',86,'93.0%','4.7%','2.3%','14.2 h','32.4 h'],['采购申请',64,'89.1%','6.2%','4.7%','24.8 h','48.2 h'],['合同审批',32,'90.6%','6.3%','3.1%','21.6 h','46.5 h'],['用印申请',21,'95.2%','0%','4.8%','6.4 h','12.8 h']].filter(r=>(adminState.reportFlow==='全部流程'||r[0]===adminState.reportFlow)&&(adminState.reportApp==='全部来源'||r[0]===(adminState.reportApp==='ERP 采购系统'?'采购申请':'费用报销'))).map(r=>adminState.reportDept==='全部部门'?r:[r[0],Math.max(1,Math.round(r[1]*0.4)),...r.slice(2)]);}
/**
 * 展示通知、存储、安全和审计配置。
 * @returns {string} 页面标记。
 */
function adminSystem(){const tab=adminState.tab;let body='';if(tab==='logs'){body=`<div class="toolbar"><input class="inp" data-filter placeholder="搜索操作 / 对象 / 操作人" value="${UI.escape(adminState.search)}"><span class="spacer"></span><button class="btn" data-action="export">导出日志</button></div><section class="panel">${adminTable(['时间','操作人','来源','操作','对象','结果'],adminState.logs.filter(l=>(l.user+l.action+l.target).includes(adminState.search)).map(l=>[l.time,l.user,'管理后台',l.action,l.target,adminPill('成功')]))}</section>`;}else if(tab==='notifications'){body=`<div class="settings-layout"><section class="panel"><div class="panel-head">消息渠道与提醒规则</div><form class="panel-body" id="notification-form"><div class="form-grid"><label class="field"><span>邮件服务器</span><input class="inp" name="smtp" value="${UI.escape(adminState.settings.smtp)}"></label><label class="field"><span>发件人名称</span><input class="inp" name="sender" value="审批服务"></label><label class="field"><span>待办汇总发送时间</span><input class="inp" type="time" name="digest" value="${adminState.settings.digest}"></label><label class="field"><span>到期前提醒</span><select class="sel" name="reminder"><option>提前 4 小时</option><option>提前 1 个工作日</option></select></label></div>${['新待办立即提醒','到期及超时通知审批人和发起人','开启每日待办汇总','评论中被 @ 时提醒'].map((n,i)=>`<label class="checkrow"><input type="checkbox" name="n${i}" ${adminState.settings.notifications[i]?'checked':''}>${n}</label>`).join('')}<div class="toolbar"><button class="btn primary" type="button" data-action="notifications-save">保存设置</button><button class="btn" type="button" data-action="mail-test">发送测试邮件</button></div></form></section><section class="panel"><div class="panel-head">渠道状态</div><div class="panel-body"><div class="status-row"><span>站内消息</span>${adminPill('已启用')}</div><div class="status-row"><span>邮件</span>${adminPill('已配置')}</div><div class="status-row"><span>企业微信 / 钉钉</span><span class="muted">后续扩展</span></div><p class="hint">每个人可在个人设置中调整提醒偏好。超时只发送提醒，不自动同意或拒绝。</p></div></section></div>`;}else if(tab==='security'){body=`<section class="panel"><div class="panel-head">登录与平台对接</div><div class="panel-body"><div class="form-grid"><label class="field"><span>登录方式</span><select class="sel"><option>本地账号 + 嵌入令牌</option><option disabled>统一登录 OIDC（预留）</option></select></label><label class="field"><span>组织可信来源</span><select class="sel"><option>审批服务</option><option disabled>公司主数据（预留）</option></select></label><label class="field"><span>访问令牌有效期（分钟）</span><input class="inp" type="number" id="token-expiry" value="${adminState.settings.tokenExpiry}" min="5" max="120"></label><label class="field"><span>出站通道</span><select class="sel"><option>直接 HTTP</option><option disabled>ESB（预留）</option></select></label></div><label class="checkrow"><input type="checkbox" checked disabled>首次登录必须修改密码</label><button class="btn primary" data-action="security-save">保存设置</button></div></section>`;}else{body=`<div class="settings-layout"><section class="panel"><div class="panel-head">附件存储</div><div class="panel-body"><div class="field"><span>存储方式</span><select class="sel" id="storage-type"><option ${adminState.settings.storage==='本地文件'?'selected':''}>本地文件</option><option ${adminState.settings.storage==='MinIO / S3'?'selected':''}>MinIO / S3</option></select></div><div class="form-grid"><label class="field"><span>数据目录 / 服务地址</span><input class="inp" id="storage-path" value="${UI.escape(adminState.settings.storagePath)}"></label><label class="field"><span>单个附件大小上限（MB）</span><input class="inp" id="file-limit" type="number" min="1" value="${adminState.settings.fileLimit}"></label></div><p class="hint">下载附件先检查审批单查看权限。本地存储的数据库和附件须一起备份。</p><div class="toolbar"><button class="btn primary" data-action="storage-save">保存配置</button><button class="btn" data-action="storage-test">连接检测</button><button class="btn" data-action="migration">迁移已有附件</button></div></div></section><section class="panel"><div class="panel-head">运行环境</div><div class="panel-body">${[['服务版本','0.1.0'],['数据库','SQLite · 单实例'],['附件总量','1.24 GB / 826 个'],['最后备份','2026-10-13 02:00'],['后台任务','正常 · 最近心跳 14:32']].map(([n,v])=>`<div class="status-row"><span class="muted">${n}</span><span>${v}</span></div>`).join('')}</div></section></div><section class="panel"><div class="panel-head">打印字体 <button class="btn sm" data-action="font-upload">上传字体</button></div>${adminTable(['字体名称','来源','字形','使用状态','操作'],adminState.fonts.map((f,i)=>[UI.escape(f),'使用单位上传','中文 / 英文',adminPill(i===0?'默认字体':'可用'),`<button class="btn ghost sm" data-action="font-default" data-id="${i}">设为默认</button>`]))}<div class="panel-body hint">请上传有授权的 TTF / OTF 字体，发布包不包含系统字体。此原型仅保存上传文件名，不读取或传输文件内容。</div></section>`;}return adminTabs([['storage','系统信息与存储'],['notifications','消息与提醒'],['security','账号与平台'],['logs','操作日志']])+body;}
